// Adventures, step 12a: the form table (fork_forms.h, generated by
// tools/gen_forms.py) and the one function that decides whether a form may be
// offered. android/FEATURES_PLAN.md, Phase 12.
//
// The table is generated, so these checks are about the RULES it must keep --
// a row that cannot be drawn is never offered, ids are stable and unique, every
// row is a real creature -- not a second copy of its values. The few named
// species below are there only to prove each mechanism actually engaged
// (CLAUDE.md § 3: "a guard phrased as X never happens needs a companion").
#include "Arduino.h"
#include "fork_adv.h"
#include "dex.h"
#include <cstdio>
#include <cstring>
#include <set>
#include <utility>

#ifndef TAMA_NATIVE_TEST
uint32_t g_seed = 1;
FakeSerial Serial;
FakeESP ESP;
FakeWire Wire;
volatile int g_touchX = 0, g_touchY = 0;
volatile bool g_touchDown = false;
bool wasPressed = false;
static uint32_t gNowMs = 0;
uint32_t millis() { return gNowMs; }
void FakeESP::restart() { exit(0); }
int FakeSerial::available() { return 0; }
String FakeSerial::readStringUntil(char) { return String(""); }
void sfxPlay(uint8_t) {}
#endif

static int bad = 0;
static void ck(bool ok, const char *what) {
  printf("%s  %s\n", ok ? "PASS" : "FAIL", what);
  if (!ok) bad++;
}

static bool ascii(const char *s) {
  for (; *s; s++)
    if ((unsigned char)*s < 0x20 || (unsigned char)*s > 0x7E) return false;
  return true;
}

// The id of a row by species and kind, ignoring art. 0 if none.
static uint8_t rowOf(int16_t dex, const char *label) {
  for (uint16_t id = 1; id <= FORM_COUNT; id++)
    if (FORM_TBL[id].dex == dex && !strcmp(FORM_TBL[id].label, label)) return (uint8_t)id;
  return 0;
}

int main() {
  // --- every row is a real creature -----------------------------------------
  bool rangeOk = true, labelOk = true, statsOk = true, typesOk = true, kindOk = true;
  bool fusionOk = true, shinyOk = true, differsOk = true;
  std::set<std::pair<int16_t, uint8_t>> keys;
  bool unique = true;
  for (uint16_t id = 1; id <= FORM_COUNT; id++) {
    const FormEntry &f = FORM_TBL[id];
    if (f.dex < 1 || f.dex > DEX_COUNT || f.sub == 0) rangeOk = false;
    if (!f.label[0] || !ascii(f.label) || strlen(f.label) > 12) labelOk = false;
    if (!f.bHp || !f.bAtk || !f.bDef || !f.bSpe || !f.bSpA || !f.bSpD) statsOk = false;
    if (f.type1 >= 18 || (f.type2 != T_NONE && (f.type2 >= 18 || f.type2 == f.type1)))
      typesOk = false;
    if (f.kind == FK_NONE || f.kind > FK_FUSION) kindOk = false;
    // "WHITE" is also Basculin's stripe and Flabebe's flower: colours, not fusions.
    if (f.kind == FK_FUSION && f.dex != 646 && f.dex != 800 && f.dex != 898) fusionOk = false;
    if (f.shinyArt && !f.art) shinyOk = false;
    // A Mega with its base species' exact stats means gen_forms.py matched the
    // base variety instead of the form. G-Max really does keep the base stats.
    const DexEntry &d = DEX_TBL[f.dex];
    if (f.kind != FK_GMAX && f.bHp == d.bHp && f.bAtk == d.bAtk && f.bDef == d.bDef &&
        f.bSpe == d.bSpe && f.bSpA == d.bSpA && f.bSpD == d.bSpD && f.type1 == d.type1 &&
        f.type2 == d.type2)
      differsOk = false;
    if (!keys.insert({ f.dex, f.sub }).second) unique = false;
  }
  ck(FORM_COUNT > 0 && FORM_TBL[0].dex == 0, "row 0 is the empty 'no form' row");
  ck(rangeOk, "every form's base species is in the dex, with a real subfolder");
  ck(labelOk, "every label is non-empty ASCII of at most 12 characters");
  ck(statsOk, "every form has six non-zero base stats");
  ck(typesOk, "every typing is a real type, second type distinct or none");
  ck(kindOk, "every form has a real kind");
  ck(fusionOk, "fusions are only Kyurem, Necrozma and Calyrex");
  ck(shinyOk, "no form claims shiny art without art");
  ck(differsOk, "no Mega/Primal/fusion is a copy of its base species");
  ck(unique, "no two rows share a species and subfolder (ids are persisted)");

  // --- a form with no art is never offered ------------------------------------
  uint16_t artless = 0, offeredArtless = 0, offered = 0;
  for (uint16_t id = 1; id <= FORM_COUNT; id++) {
    if (!FORM_TBL[id].art) artless++;
    if (forkFormUsable((uint8_t)id)) {
      offered++;
      if (!FORM_TBL[id].art) offeredArtless++;
    }
  }
  // The companion: without art-less rows, "none is offered" would be vacuous.
  ck(artless > 0, "the table holds art-less rows, so the next check can fail");
  ck(offeredArtless == 0, "no art-less form is usable");
  ck(offered > 0 && offered < FORM_COUNT, "some forms are usable, not all");

  // forkFormsOf() must agree with forkFormUsable() for every species, and must
  // count exactly the usable forms, not every row.
  bool agree = true;
  for (int16_t dex = 1; dex <= DEX_COUNT; dex++) {
    uint8_t ids[16];
    uint8_t n = forkFormsOf(dex, FK_NONE, ids, 16);
    uint8_t want = 0;
    for (uint16_t id = 1; id <= FORM_COUNT; id++)
      if (FORM_TBL[id].dex == dex && forkFormUsable((uint8_t)id)) want++;
    if (n != want) agree = false;
    for (uint8_t i = 0; i < n && i < 16; i++)
      if (!forkFormUsable(ids[i]) || FORM_TBL[ids[i]].dex != dex) agree = false;
  }
  ck(agree, "forkFormsOf() lists exactly the usable forms of each species");

  // The mechanism, on the one species with all three outcomes: Charizard has a
  // Mega X with art, a Mega Y without, and a G-Max with art.
  const uint8_t mx = rowOf(6, "MEGA X"), my = rowOf(6, "MEGA Y"), gx = rowOf(6, "G-MAX");
  ck(mx && my && gx, "Charizard has Mega X, Mega Y and G-Max rows");
  uint8_t ids[4];
  uint8_t n = forkFormsOf(6, FK_NONE, ids, 4);
  bool hasX = false, hasY = false, hasG = false;
  for (uint8_t i = 0; i < n; i++) {
    hasX |= ids[i] == mx;
    hasY |= ids[i] == my;
    hasG |= ids[i] == gx;
  }
  ck(n == 2 && hasX && hasG && !hasY, "Charizard offers Mega X and G-Max, never the art-less Mega Y");
  ck(forkFormsOf(6, FK_MEGA, nullptr, 0) == 1, "filtering by kind counts only that kind");
  ck(forkFormsOf(6, FK_FUSION, nullptr, 0) == 0, "a kind a species lacks counts zero");
  ck(forkFormsOf(6, FK_NONE, ids, 1) == 2, "the count is the total even when `max` is smaller");

  // --- lookups ----------------------------------------------------------------
  ck(forkForm(0) == nullptr && forkForm(FORM_COUNT + 1) == nullptr, "id 0 and past the end are no form");
  // By content, not address: FORM_TBL is `static const` in a header, so every
  // translation unit holds its own copy.
  bool rowsMatch = true;
  for (uint16_t id = 1; id <= FORM_COUNT; id++) {
    const FormEntry *f = forkForm((uint8_t)id);
    if (!f || f->dex != FORM_TBL[id].dex || f->sub != FORM_TBL[id].sub) rowsMatch = false;
  }
  ck(rowsMatch, "every real id is its own row");
  ck(!forkFormUsable(0), "id 0 is never usable");
  ck(forkFormIsState(FK_MEGA) && forkFormIsState(FK_PRIMAL) && forkFormIsState(FK_GMAX) &&
         forkFormIsState(FK_ULTRA),
     "Mega, Primal, G-Max and Ultra are battle states");
  ck(!forkFormIsState(FK_FUSION) && !forkFormIsState(FK_NONE), "a fusion is a creature, not a state");

  // --- mythicals ------------------------------------------------------------
  // The rule: every mythical is in dex.h's legendary tier, or is reached by
  // evolving from it (PHIONE -> MANAPHY). Nothing else can be.
  bool mythInTier = true, mythSorted = true;
  for (uint8_t i = 0; i < MYTHICAL_COUNT; i++) {
    const int16_t d = MYTHICAL_DEX[i];
    if (i && MYTHICAL_DEX[i - 1] >= d) mythSorted = false;
    bool ok = d >= 1 && d <= DEX_COUNT && DEX_TBL[d].rarity == R_LEGENDARIO;
    for (int16_t s = 1; s <= DEX_COUNT && !ok && d >= 1 && d <= DEX_COUNT; s++)
      if (DEX_TBL[s].rarity == R_LEGENDARIO) {
        for (int16_t n = DEX_TBL[s].evolvesTo, hop = 0; n && hop < 4; n = DEX_TBL[n].evolvesTo, hop++)
          if (n == d) ok = true;
      }
    if (!ok) mythInTier = false;
  }
  ck(MYTHICAL_COUNT > 0 && mythSorted, "the mythical list is non-empty, sorted and has no repeats");
  ck(mythInTier, "every mythical is legendary-tier or evolves from it");
  ck(forkIsMythical(151) && !forkIsMythical(150), "MEW is mythical, MEWTWO is not");
  // The one a tier-only derivation missed: MANAPHY is R_EVO in dex.h.
  ck(forkIsMythical(490) && DEX_TBL[490].rarity != R_LEGENDARIO, "MANAPHY is mythical though not legendary-tier");
  ck(!forkIsMythical(0) && !forkIsMythical(25), "nothing outside the list is");

  printf("%s (%d failed)\n", bad ? "FORMS_TEST FAILED" : "ALL PASS", bad);
  return bad ? 1 : 0;
}
